    let var_info = &mut context.var_info[var_index];
    // We should never visit the variable again, so it's safe to take the name away.
    let var_name = var_info
        .var
        .take()
        .expect("Variable should not be popped from stack twice");
    if var_index != index {
        // Anything here is in a loop which can traverse to the node we are handling, so
        // it's invalid at computed-value time.
        in_loop = true;
    }
    if in_loop {
        context.handle_loop(&var_name);
        if let VarType::NonCustom(longhand) = var_name {
            context.prepared_priorities.remove(&longhand);
            invalid_priorities.push(PrioritaryPropertyId::from_longhand(longhand).unwrap());
        }
    }
    if var_index == index {
        debug_assert_eq!(var_name, var);
        break;
    }
}

if in_loop {
    for id in invalid_priorities {
        context.cascade.ensure_prioritary_property(
            context.computed_context,
            context.decls,
            context.cache,
            attribute_tracker,
            id,
        );
    }
    return None;
}

