        && lowlink == index
        && !self_ref
        && context.stack.last() == Some(&index)
    {
        let prepared = prepare_custom_value(
            name,
            v,
            context.stylist,
            context.computed_context,
            attribute_tracker,
        );
        if prepared.depends_on_color_scheme() {
            value_non_custom_refs |= ReferenceFlags::COLOR_SCHEME;
        }
        prepared_custom = Some(prepared);
    }
}

